    /**
     * Class to manage the WT21 Half Bank Setting
     */
    class WT21VariableBankManager {
        /**
         * Creates an instance of the WT21 Variable Bank Manager.
         * @param bus The event bus to use with this instance.
         * @param apValues The autopilot ap values.
         */
        constructor(bus, apValues) {
            this.bus = bus;
            this.apValues = apValues;

            this.halfBankActivationAltitude = 31600;
            this.halfBankSetAtActivationAltitide = false;
            this.fullBankSetAtActivationAltitide = false;


            this.halfBankWasAboveTransition = null;
            this.fullBankCalculatorValue = 25;

            this.halfBankCalculatorValue = 15;
            /**
             * Handles when the max bank index changes from the sim autopilot values.
             * @param index The max_bank_id value.
             */
            this.handleMaxBankIndexChanged = (index) => {
                const options = { bankAngle: index === WT21MaxBankIndex.FULL_BANK ? this.fullBankCalculatorValue : this.halfBankCalculatorValue };
                this.publisher.pub('flightpath_set_options', options, true, true);
            };
            /**
             * Handles when the aircraft indicated altitude changes (evaluated in 10' increments).
             * @param altitude The indicated altitude in feet AMSL.
             */

            this.handleAltitudeUpdated = (altitude) => {
                const above = altitude > this.halfBankActivationAltitude;
                if (this.halfBankWasAboveTransition === null) {

                    this.halfBankWasAboveTransition = above;
                    if (above && this.maxBankIndex.get() === WT21MaxBankIndex.FULL_BANK) {
                        SimVar.SetSimVarValue('K:AP_MAX_BANK_SET', 'number', WT21MaxBankIndex.HALF_BANK);
                    }
                    return;
                }
                if (above === this.halfBankWasAboveTransition) {
                    return;
                }
                this.halfBankWasAboveTransition = above;
                SimVar.SetSimVarValue('K:AP_MAX_BANK_SET', 'number',
                    above ? WT21MaxBankIndex.HALF_BANK : WT21MaxBankIndex.FULL_BANK);
            };
            /**
             * Handles when the lateral active AP mode changes.
             * @param mode The Active Lateral AP Mode.
             */
            this.handleLateralActiveChanged = (mode) => {
                if (mode === msfsSdk.APLateralModes.GPSS) {

                    if (this.altitude.get() > this.halfBankActivationAltitude
                        && this.maxBankIndex.get() === WT21MaxBankIndex.FULL_BANK) {
                        SimVar.SetSimVarValue('K:AP_MAX_BANK_SET', 'number', WT21MaxBankIndex.HALF_BANK);
                    }
                }
            };
            this.publisher = this.bus.getPublisher();
            const adc = this.bus.getSubscriber();
            const ap = this.bus.getSubscriber();
            this.altitude = msfsSdk.ConsumerSubject.create(adc.on('indicated_alt').whenChangedBy(10), 0);
            this.maxBankIndex = msfsSdk.ConsumerSubject.create(ap.on('ap_max_bank_id').whenChanged(), WT21MaxBankIndex.FULL_BANK);
            this.maxBankValue = msfsSdk.ConsumerSubject.create(ap.on('ap_max_bank_value').whenChanged(), 30);
            // Sets the correct variable bank rate for the altitude.
            this.altitude.sub(this.handleAltitudeUpdated, true);
            // Sets the correct variable bank rate for the altitude when LNAV is engaged.
            this.apValues.lateralActive.sub(this.handleLateralActiveChanged, true);
            // Sets the max bank angle to be used by FlightPathCalculator to calculate the flight path.
            this.maxBankIndex.sub(this.handleMaxBankIndexChanged, true);
            // Sets the max bank angle the AP may command.
            this.maxBankValue.sub(v => this.apValues.maxBankAngle.set(v), true);
        }
    }

