    /**
     * The FMC ATC Control page.
     */
    class AtcControlPage extends FmcPage {
        constructor() {
            super(...arguments);
            this.identSub = msfsSdk.Subject.create(false);
            this.codeSub = msfsSdk.Subject.create(0);
            this.altReportSub = msfsSdk.Subject.create(0);
            this.modeSub = msfsSdk.Subject.create(0);
            this.pressureAlt = msfsSdk.ConsumerSubject.create(null, 0);
            this.CodeInput = new TextInputField(this, {
                formatter: new TransponderCodeFormat(),
                style: '[green]',
                onSelected: async (scratchpadContents) => {
                    if (scratchpadContents.length === 0) {
                        this.setActiveRoute('/tune/1');
                        return true;
                    }
                    return false;
                }
            }).bind(this.codeSub);
            this.AltReportSwitch = new SwitchLabel(this, {
                optionStrings: ['ON', 'OFF'],
                activeStyle: 'blue'
            }).bind(this.altReportSub);
            this.PressureAltField = new DisplayField(this, {
                formatter: {
                    nullValueString: 'ALT [white] ---- FT[green]',
                    /** @inheritDoc */
                    format(value) {
                        return `ALT[white] ${value} FT[green]`;
                    },
                },
            }).bind(this.pressureAlt);
            this.IdentButton = new DisplayField(this, {
                formatter: {
                    nullValueString: 'IDENT',
                    /** @inheritDoc */
                    format(value) {
                        return `IDENT[${value ? 'blue' : 'white'} s-text]`;
                    },
                },
                onSelected: async () => {
                    await SimVar.SetSimVarValue('K:XPNDR_IDENT_ON', msfsSdk.SimVarValueType.Bool, true);
                    return true;
                },
            }).bind(this.identSub);
            this.XpdrSwitch = new SwitchLabel(this, {
                optionStrings: ['ATC1', 'ATC2'],
                activeStyle: 'blue',
                disabled: true
            });
            this.ModeSwitch = new SwitchLabel(this, {
                optionStrings: ['ON', 'STBY'],
                activeStyle: 'blue'
            }).bind(this.modeSub);
        }
        /** @inheritdoc */
        onInit() {
            // TODO: Support two transponders
            const pub = this.eventBus.getPublisher();
            const sub = this.eventBus.getSubscriber();
            // Update code input field from transponder code
            this.addBinding(sub.on('xpdr_code_1').whenChanged().handle((code => {
                this.codeSub.set(code);
            })));
            // Update mode and alt reporting switches from transponder mode
            this.addBinding(sub.on('xpdr_mode_1').whenChanged().handle(mode => {
                switch (mode) {
                    case msfsSdk.XPDRMode.ON:
                        this.modeSub.set(0);
                        this.altReportSub.set(1);
                        break;
                    case msfsSdk.XPDRMode.ALT:
                        this.modeSub.set(0);
                        this.altReportSub.set(0);
                        break;
                    case msfsSdk.XPDRMode.OFF:
                    case msfsSdk.XPDRMode.STBY:
                        this.modeSub.set(1);
                        break;
                }
            }));
            // Update transponder ident
            this.addBinding(sub.on('xpdr_ident_1').whenChanged().handle((ident) => this.identSub.set(ident)));
            // Update transponder code from code input
            this.addBinding(this.codeSub.sub(code => {
                pub.pub('publish_xpdr_code_1', code, true, false);
            }));
            // Update transponder mode from mode switch
            this.addBinding(this.modeSub.sub(val => {
                const mode = val === 0
                    ? this.altReportSub.get() === 0 ? msfsSdk.XPDRMode.ALT : msfsSdk.XPDRMode.ON
                    : msfsSdk.XPDRMode.STBY;
                pub.pub('publish_xpdr_mode_1', mode, true, false);
            }));
            // Update transponder mode from alt reporting switch
            this.addBinding(this.altReportSub.sub(val => {
                if (this.modeSub.get() === 0) {
                    pub.pub('publish_xpdr_mode_1', val === 0 ? msfsSdk.XPDRMode.ALT : msfsSdk.XPDRMode.ON, true, false);
                }
            }));
            this.pressureAlt.setConsumer(sub.on('pressure_alt').withPrecision(-2));
        }
        /** @inheritdoc */
        render() {
            return [
                [
                    ['ATC CONTROL[blue]'],
                    [' ATC1', 'ALT REPORT '],
                    [this.CodeInput, this.AltReportSwitch],
                    ['', '', this.PressureAltField],
                    [this.IdentButton, 'TEST[s-text]'],
                    [''],
                    [''],
                    [' SELECT', ''],
                    [this.XpdrSwitch, ''],
                    [' MODE'],
                    [this.ModeSwitch, '']
                ]
            ];
        }
        /** @inheritdoc */
        onDestroy() {
            this.pressureAlt.destroy();
        }
    }

