                    ['', ''],
                    [this.NextButton, ''],
                    ['', ''],
                    ['<TO WPT', ''],
                    [' CTR WPT[blue]', ''],
                    [this.ctrIdentField, ''],
                    ['', ''],
                    ['', ''],
                    ['', 'SIDE[blue]'],
                    ['', this.sideSwitch]
