    /**
     * Utility for predicting ALTN data
     */
    class WT21AlternatePredictor {
        /**
         * Ctor
         * @param planner the flight planner
         * @param facLoader the facility loader
         * @param predictor the flight plan predictor
         */
        constructor(planner, facLoader, predictor) {
            this.planner = planner;
            this.facLoader = facLoader;
            this.predictor = predictor;
            /**
             * The current predictions for the alternate destination
             */
            this.alternateData = {
                kind: 'activeOrUpcoming',
                ident: '',
                distance: 0,
                fob: 0,
                estimatedTimeEnroute: 0,
                estimatedTimeOfArrival: 0,
            };
            this.alternatePredictions = null;
            this._cachedDestinationFacility = null;
            this._cachedAlternateFacility = null;
            this._destinationPos = new msfsSdk.GeoPoint(0, 0);
            this._alternatePos = new msfsSdk.GeoPoint(0, 0);
        }
        /**
         * Update loop
         */
        async update() {
            if (this.planner.hasFlightPlan(WT21Fms.PRIMARY_ACT_PLAN_INDEX)) {
                const plan = this.planner.getFlightPlan(WT21Fms.PRIMARY_ACT_PLAN_INDEX);
                const destinationFacilityIcao = plan.destinationAirport;
                if (destinationFacilityIcao && destinationFacilityIcao !== msfsSdk.ICAO.emptyIcao) {
                    let destinationFacility = this._cachedDestinationFacility;
                    if (!destinationFacility || destinationFacility.icao !== destinationFacilityIcao) {
                        destinationFacility = await this.facLoader.getFacility(msfsSdk.FacilityType.Airport, destinationFacilityIcao);
                        this._cachedDestinationFacility = destinationFacility;
                    }
                    if (destinationFacility) {
                        this._destinationPos.set(destinationFacility.lat, destinationFacility.lon);
                        const destinationPredictions = this.predictor.getDestinationPrediction(destinationFacility);
                        if (destinationPredictions) {
                            const destinationDistance = destinationPredictions.distance;
                            const altnFacilityIcao = plan.getUserData(WT21Fms.USER_DATA_KEY_ALTN);
                            if (altnFacilityIcao && altnFacilityIcao !== msfsSdk.ICAO.emptyIcao) {
                                let altnFacility = this._cachedAlternateFacility;
                                if (!altnFacility || altnFacility.icao !== altnFacilityIcao) {
                                    altnFacility = await this.facLoader.getFacility(msfsSdk.FacilityType.Airport, altnFacilityIcao);
                                    this._cachedAlternateFacility = altnFacility;
                                }
                                if (altnFacility) {
                                    this._alternatePos.set(altnFacility.lat, altnFacility.lon);
                                    this.alternateData.ident = msfsSdk.ICAO.getIdent(altnFacilityIcao);
                                    const destinationToAlternateDistance = this._destinationPos.distance(this._alternatePos);
                                    const destinationToAlternateDistanceNM = msfsSdk.UnitType.NMILE.convertFrom(destinationToAlternateDistance, msfsSdk.UnitType.GA_RADIAN);
                                    const totalDistanceToAlternate = destinationDistance + destinationToAlternateDistanceNM;
                                    this.alternateData.distance = totalDistanceToAlternate;
                                    this.predictor.applyPredictionsForDistance(totalDistanceToAlternate, this.alternateData);
                                    this.alternatePredictions = this.alternateData;
                                    return;
                                }
                            }
                        }
                    }
                }
            }
            this.alternatePredictions = null;
        }
    }

    /**
     * Rounds a number to an integer if > 100, or to a float with one decimal digit otherwise
     *
     * @param distance in nautical miles
     *
     * @returns the rounded number string
     */
    function formatNumberForDistance(distance) {
        if (distance > 9999) {
            return '9999'; // Not sure if this is accurate, but this what I've seen those systems do
        }
        else if (distance > 100) {
            return Math.trunc(distance).toString();
        }
        else {
            return distance.toFixed(1);
        }
    }
