            // eslint-disable-next-line jsdoc/require-jsdoc
            this.canActivateNoFlightPlanMessage = () => {
                const isFmsActiveNavSource = this.fms.getCdiSource().type === msfsSdk.NavSourceType.Gps;
                const noActiveFlightPlan = !this.fms.hasPrimaryFlightPlan() || this.fms.getPrimaryFlightPlan().length === 0;
                return isFmsActiveNavSource && noActiveFlightPlan;
            };
            RegisterViewListener('JS_LISTENER_INSTRUMENTS');
            SimVar.SetSimVarValue('L:XMLVAR_NEXTGEN_FLIGHTPLAN_ENABLED', msfsSdk.SimVarValueType.Bool, true);
